Box(contentAlignment = Alignment.TopCenter) {
    // The faint status numeral behind the icon, as the web page draws it.
    Text(
        text = "404",
        modifier = Modifier.padding(top = MonarchTheme.spacing.space2).clearAndSetSemantics { },
        color = MonarchTheme.colors.bgEmphasis,
        fontSize = 96.sp,
        fontWeight = FontWeight.SemiBold,
    )
    MonarchErrorState(
        title = {{title}},
        kind = MonarchErrorStateKind.{{kind|pascal}},
        size = MonarchEmptyStateSize.Lg,
        pageTile = true,
        message = {{description}},
        icon = { MonarchIcon(SampleIcons.Search, contentDescription = null) },
        actions = {
            MonarchButton(text = {{primaryAction}}, onClick = {}, variant = MonarchButtonVariant.Primary)
            MonarchButton(text = {{secondaryAction}}, onClick = {})
        },
    )
}

